with with_windows as (select id, channel, promo_code, starts_on, ends_on, discount_pct, min(discount_pct) over (partition by promo_code, channel) as promo_code_min_discount_pct, row_number() over (partition by promo_code order by discount_pct desc, id) as event_seq, first_value(channel, true) over (partition by channel order by discount_pct, id rows between unbounded preceding and current row) as first_known_channel from promotions) select id, channel, ends_on, discount_pct, promo_code_min_discount_pct, event_seq, first_known_channel, case when channel rlike '^(partner|web)$' then 'OTHER_ZONE' else 'CORE' end as channel_zone from with_windows;
